/**
 * Updates ONLY the Auth URL configuration on a hosted Supabase project.
 *
 * Usage:
 *   SUPABASE_ACCESS_TOKEN=sbp_… node scripts/set-auth-redirects.mjs [--dry-run]
 *
 * Why not `supabase config push`?
 * -------------------------------
 * That command diffs the whole of `supabase/config.toml` against the remote and
 * pushes every declared property. A local config generated by `supabase init`
 * carries *defaults*, so pushing it would also have flipped the hosted project's
 * `auth.email.enable_confirmations` from true to false (removing email
 * verification), shortened `auth.email.otp_length` from 8 to 6, and rewritten
 * pooler, MFA and storage settings — none of which this task needs.
 *
 * This script therefore patches only `site_url` and `uri_allow_list` through the
 * Management API, and leaves everything else exactly as the dashboard has it.
 *
 * The token is read from the environment or `.env.local` and is never printed.
 */
import { existsSync, readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const root = dirname(dirname(fileURLToPath(import.meta.url)))

function loadEnvFile(path) {
  const out = {}
  if (!existsSync(path)) return out
  for (const rawLine of readFileSync(path, 'utf8').split(/\r?\n/)) {
    const line = rawLine.trim()
    if (!line || line.startsWith('#')) continue
    const eq = line.indexOf('=')
    if (eq === -1) continue
    const key = line.slice(0, eq).trim()
    let value = line.slice(eq + 1).trim()
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1)
    }
    out[key] = value
  }
  return out
}

const fileEnv = loadEnvFile(join(root, '.env.local'))
const token = process.env.SUPABASE_ACCESS_TOKEN || fileEnv.SUPABASE_ACCESS_TOKEN
const projectRef = process.env.SUPABASE_PROJECT_REF || fileEnv.SUPABASE_PROJECT_REF

if (!token) {
  console.error('No access token. Set SUPABASE_ACCESS_TOKEN or add it to .env.local.')
  process.exit(2)
}
if (!projectRef) {
  console.error('No project ref. Set SUPABASE_PROJECT_REF or add it to .env.local.')
  process.exit(2)
}

const siteUrl = process.env.SITE_URL || 'https://anusree-daily-tracker.vercel.app'

// GoTrue matches redirect targets against this comma-separated allow-list.
// `/**` covers the SPA's client-side routes.
const allowList = [
  'https://anusree-daily-tracker.vercel.app/**',
  'https://anusree-daily-tracker-*.vercel.app/**',
  'http://localhost:5173/**',
  'http://127.0.0.1:5173/**',
].join(',')

const dryRun = process.argv.includes('--dry-run')
const api = 'https://api.supabase.com/v1'
const headers = {
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
}

console.log(`project     : ${projectRef}`)
console.log(`site_url    : ${siteUrl}`)
console.log(`allow-list  : ${allowList}`)

/* -- 1. read the current config so nothing is clobbered -------------------- */
const beforeResponse = await fetch(`${api}/projects/${projectRef}/config/auth`, { headers })
if (!beforeResponse.ok) {
  const body = await beforeResponse.text()
  console.error(`\nCould not read the auth config: HTTP ${beforeResponse.status} ${body.slice(0, 200)}`)
  process.exit(1)
}
const before = await beforeResponse.json()
console.log(`\nbefore site_url      : ${before.site_url}`)
console.log(`before uri_allow_list: ${before.uri_allow_list || '(empty)'}`)
console.log(`before otp_length    : ${before.mailer_otp_exp ?? before.otp_length ?? '(unchanged)'}`)
console.log(`before email confirm : ${before.mailer_autoconfirm === false ? 'enabled' : String(before.mailer_autoconfirm)}`)

if (dryRun) {
  console.log('\n--dry-run: no changes sent.')
  process.exit(0)
}

/* -- 2. patch only the two URL properties --------------------------------- */
const patchResponse = await fetch(`${api}/projects/${projectRef}/config/auth`, {
  method: 'PATCH',
  headers,
  // Deliberately just these two keys. Any additional property here would be an
  // unintended change to the hosted project.
  body: JSON.stringify({ site_url: siteUrl, uri_allow_list: allowList }),
})

if (!patchResponse.ok) {
  const body = await patchResponse.text()
  console.error(`\nUpdate failed: HTTP ${patchResponse.status} ${body.slice(0, 300)}`)
  process.exit(1)
}

/* -- 3. confirm the read-back reflects the change ------------------------- */
const after = await (await fetch(`${api}/projects/${projectRef}/config/auth`, { headers })).json()
const allowOk = String(after.uri_allow_list ?? '').includes('anusree-daily-tracker.vercel.app')
const siteOk = after.site_url === siteUrl

console.log(`\nafter site_url       : ${after.site_url}  ${siteOk ? 'OK' : 'MISMATCH'}`)
console.log(`after uri_allow_list : ${after.uri_allow_list}`)
console.log(`allow-list correct   : ${allowOk ? 'OK' : 'MISMATCH'}`)

// Confirm the settings we deliberately left alone are unchanged.
const confirmationsUnchanged = before.mailer_autoconfirm === after.mailer_autoconfirm
const otpUnchanged =
  (before.mailer_otp_exp ?? null) === (after.mailer_otp_exp ?? null) &&
  (before.otp_length ?? null) === (after.otp_length ?? null)

console.log(`email confirmations untouched : ${confirmationsUnchanged ? 'OK' : 'CHANGED'}`)
console.log(`otp length untouched          : ${otpUnchanged ? 'OK' : 'CHANGED'}`)

process.exit(siteOk && allowOk && confirmationsUnchanged && otpUnchanged ? 0 : 1)
